package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.XmlDeclaration;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class XmlDeclaration_getWholeDeclaration_TriageGen2Test {

    @Test
    public void test_getWholeDeclaration_xml_no_attributes() {
        XmlDeclaration xml = new XmlDeclaration("xml", null, false);
        assertEquals("xml", xml.getWholeDeclaration());
    }

    @Test
    public void test_getWholeDeclaration_xml_one_attribute() {
        XmlDeclaration xml = new XmlDeclaration("xml", null, false);
        xml.attributes().put("version", "1.0");
        assertEquals("xml version=\"1.0\"", xml.getWholeDeclaration());
    }

    @Test
    public void test_getWholeDeclaration_xml_two_attributes() {
        XmlDeclaration xml = new XmlDeclaration("xml", null, false);
        xml.attributes().put("version", "1.0");
        xml.attributes().put("encoding", "utf-8");
        assertEquals("xml version=\"1.0\" encoding=\"utf-8\"", xml.getWholeDeclaration());
    }

    @Test
    public void test_getWholeDeclaration_xml_no_version_attribute() {
        XmlDeclaration xml = new XmlDeclaration("xml", null, false);
        xml.attributes().put("encoding", "utf-8");
        assertEquals("xml encoding=\"utf-8\"", xml.getWholeDeclaration());
    }

    @Test
    public void test_getWholeDeclaration_xml_version_attribute_only() {
        XmlDeclaration xml = new XmlDeclaration("xml", null, false);
        xml.attributes().put("version", "1.0");
        assertEquals("xml version=\"1.0\"", xml.getWholeDeclaration());
    }

    @Test
    public void test_getWholeDeclaration_not_xml() {
        XmlDeclaration xml = new XmlDeclaration("tag", null, false);
        assertEquals("tag", xml.getWholeDeclaration());
    }

    @Test
    public void test_getWholeDeclaration_xml_null_attributes() {
        XmlDeclaration xml = new XmlDeclaration("xml", null, false);
        assertNull(xml.getWholeDeclaration());
    }

    @Test
    public void test_getWholeDeclaration_xml_attributes_empty_map() {
        XmlDeclaration xml = new XmlDeclaration("xml", null, false);
        xml.attributes().clear();
        assertEquals("xml", xml.getWholeDeclaration());
    }

    @Test
    public void test_getWholeDeclaration_xml_attributes_null() {
        XmlDeclaration xml = new XmlDeclaration("xml", null, false);
        xml.attributes().nullAttributes();
        assertEquals("xml", xml.getWholeDeclaration());
    }
}
